save_refinement_preference:
def save_refinement_preference(self) -> None:
    try:
        settings = replace(load_settings(self.settings_path), refine_translations=self.refine_translations.get())
        save_settings(self.settings_path, settings, require_model=False)
    except (OSError, ValueError, TypeError) as exc:
        messagebox.showerror("Cannot save refinement option", str(exc), parent=self.root)

refine_selected:
def refine_selected(self):
    indices = [int(index) for index in self.app.tree.selection()]
    if not indices:
        messagebox.showinfo("Select chunks", "Select translated chunks in the queue first.", parent=self.app.root)
        return
    try:
        engine = self.current_engine()
    except (OSError, ValueError, TypeError) as exc:
        messagebox.showerror("Cannot refine translations", str(exc), parent=self.app.root)
        return
    self.app._background(lambda: engine.refine_chunks(indices))
